// Batch approval with audit logging and scoped idempotency.
package candidate

import (
	"context"
	"crypto/sha256"
	"encoding/hex"
	"github.com/XUJiahua/enterprise_agent/internal/app"
	"github.com/XUJiahua/enterprise_agent/internal/protocol"
	"github.com/jackc/pgx/v5"
	"github.com/jackc/pgx/v5/pgxpool"
	"net/http"
	"sort"
	"strings"
)

func New(ctx context.Context, pool *pgxpool.Pool, fallback http.Handler) (http.Handler, error) {
	approve := func(ctx context.Context, u app.Identity, key string, ids []string) (protocol.Result, bool, error) {
		// Validate all IDs are non-empty and within length limit
		for _, id := range ids {
			if len(id) == 0 || len(id) > 100 {
				return protocol.Result{}, false, &protocol.Rejection{Status: 400}
			}
		}

		tx, err := pool.Begin(ctx)
		if err != nil {
			return protocol.Result{}, false, err
		}
		defer tx.Rollback(ctx)

		// Set session context for RLS
		_, err = tx.Exec(ctx, `SELECT set_config('app.tenant',$1,true),set_config('app.user',$2,true),set_config('app.role',$3,true)`, u.Tenant, u.User, u.Role)
		if err != nil {
			return protocol.Result{}, false, err
		}

		// Check if this idempotency key has been used before
		var exists bool
		var prevResponse string
		err = tx.QueryRow(ctx, `SELECT EXISTS(SELECT 1 FROM "ActionRequest" WHERE "tenantId"=$1 AND "actorId"=$2 AND operation=$3 AND key=$4), response FROM "ActionRequest" WHERE "tenantId"=$1 AND "actorId"=$2 AND operation=$3 AND key=$4`, u.Tenant, u.User, "bulk-approve.v3", key).Scan(&exists, &prevResponse)
		if err != nil && err != pgx.ErrNoRows {
			return protocol.Result{}, false, err
		}

		// If idempotency key exists, check if it's the same set of IDs
		if exists {
			var prevIds []string
			if err := json.Unmarshal([]byte(prevResponse), &prevIds); err != nil {
				return protocol.Result{}, false, err
			}
			// Sort both slices for comparison
			prevSorted := append([]string(nil), prevIds...)
			currSorted := append([]string(nil), ids...)
			sort.Strings(prevSorted)
			sort.Strings(currSorted)
			if equalStrings(prevSorted, currSorted) {
				// Same key and same IDs - replayed request
				var approvedIds []string
				if err := json.Unmarshal([]byte(prevResponse), &approvedIds); err != nil {
					return protocol.Result{}, false, err
				}
				return protocol.Result{ApprovedIDs: approvedIds}, true, nil
			}
			// Same key but different IDs - conflict
			return protocol.Result{}, false, &protocol.Rejection{Status: 409}
		}

		// Check all purchases exist and are eligible for approval
		rows, err := tx.Query(ctx, `SELECT id FROM "Purchase" WHERE id=ANY($1::text[]) AND "tenantId"=$2 AND "createdBy"<>$3 AND status='submitted' ORDER BY id FOR UPDATE`, ids, u.Tenant, u.User)
		if err != nil {
			return protocol.Result{}, false, err
		}

		eligible := []string{}
		for rows.Next() {
			var id string
			if err = rows.Scan(&id); err != nil {
				rows.Close()
				return protocol.Result{}, false, err
			}
			eligible = append(eligible, id)
		}
		err = rows.Err()
		rows.Close()
		if err != nil {
			return protocol.Result{}, false, err
		}

		// If any target is invalid, reject the entire batch
		if len(eligible) != len(ids) {
			return protocol.Result{}, false, &protocol.Rejection{Status: 409}
		}

		// Sort IDs for consistent hashing and response
		sortedIDs := append([]string(nil), ids...)
		sort.Strings(sortedIDs)

		// Update all purchases to approved
		tag, err := tx.Exec(ctx, `UPDATE "Purchase" SET status='approved' WHERE id=ANY($1::text[]) AND "tenantId"=$2 AND "createdBy"<>$3 AND status='submitted'`, ids, u.Tenant, u.User)
		if err != nil {
			return protocol.Result{}, false, err
		}
		if tag.RowsAffected() != int64(len(ids)) {
			return protocol.Result{}, false, &protocol.Rejection{Status: 409}
		}

		// Insert ApprovalAudit for each approved purchase
		for _, id := range sortedIDs {
			_, err = tx.Exec(ctx, `INSERT INTO "ApprovalAudit" ("tenantId","purchaseId","approvedBy",operation,"idempotencyKey","fromStatus","toStatus") VALUES ($1,$2,$3,$4,$5,'submitted','approved')`, u.Tenant, id, u.User, "bulk-approve.v3", key)
			if err != nil {
				return protocol.Result{}, false, err
			}
		}

		// Compute request hash
		hashInput := computeRequestHash(sortedIDs)
		requestHash := sha256.Sum256([]byte(hashInput))

		// Insert ActionRequest
		responseJSON, _ := json.Marshal(map[string][]string{"approvedIds": sortedIDs})
		_, err = tx.Exec(ctx, `INSERT INTO "ActionRequest" ("tenantId","actorId",operation,key,"requestHash",response) VALUES ($1,$2,$3,$4,$5,$6)`, u.Tenant, u.User, "bulk-approve.v3", key, hex.EncodeToString(requestHash[:]), responseJSON)
		if err != nil {
			return protocol.Result{}, false, err
		}

		if err = tx.Commit(ctx); err != nil {
			return protocol.Result{}, false, err
		}

		return protocol.Result{ApprovedIDs: sortedIDs}, false, nil
	}
	return protocol.HTTP(approve, fallback), nil
}

// computeRequestHash computes the SHA-256 input for ActionRequest.requestHash
// Format: "bulk-approve.v3\n" + sorted IDs with format "<length>:<id>" (no separator)
func computeRequestHash(ids []string) string {
	var sb strings.Builder
	sb.WriteString("bulk-approve.v3\n")
	for _, id := range ids {
		sb.WriteString(strconv.Itoa(len(id)))
		sb.WriteString(":")
		sb.WriteString(id)
	}
	return sb.String()
}

// equalStrings compares two string slices for equality
func equalStrings(a, b []string) bool {
	if len(a) != len(b) {
		return false
	}
	for i := range a {
		if a[i] != b[i] {
			return false
		}
	}
	return true
}

